<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_role('admin');
$studentId = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if (!$studentId) { set_flash('danger', 'Invalid student.'); redirect('admin/students.php'); }
$statement = db()->prepare("SELECT u.id, u.first_name, u.last_name, u.email, u.status, p.total_xp, p.level, p.current_streak, p.longest_streak FROM users u INNER JOIN student_profiles p ON p.user_id = u.id WHERE u.id = :id AND u.role = 'student'"); $statement->execute(['id' => $studentId]); $student = $statement->fetch(); if (!$student) { set_flash('danger', 'Student not found.'); redirect('admin/students.php'); }
$courses = db()->prepare("SELECT c.title, e.enrolled_at, e.completed_at, COUNT(DISTINCT l.id) AS total_lessons, COUNT(DISTINCT lp.id) AS completed_lessons FROM enrollments e INNER JOIN courses c ON c.id = e.course_id LEFT JOIN lessons l ON l.course_id = c.id AND l.status = 'published' LEFT JOIN lesson_progress lp ON lp.lesson_id = l.id AND lp.user_id = e.user_id WHERE e.user_id = :id GROUP BY c.id, c.title, e.enrolled_at, e.completed_at ORDER BY e.enrolled_at DESC"); $courses->execute(['id' => $studentId]); $courses = $courses->fetchAll();
$achievements = db()->prepare('SELECT a.name, sa.completed_at FROM student_achievements sa INNER JOIN achievements a ON a.id = sa.achievement_id WHERE sa.user_id = :id'); $achievements->execute(['id' => $studentId]); $achievements = $achievements->fetchAll(); $badges = db()->prepare('SELECT b.name, sb.awarded_at FROM student_badges sb INNER JOIN badges b ON b.id = sb.badge_id WHERE sb.user_id = :id'); $badges->execute(['id' => $studentId]); $badges = $badges->fetchAll();
$pageTitle = 'Student profile'; require __DIR__ . '/../includes/header.php';
?>
<div class="py-4"><a href="<?= e(app_url('admin/students.php')) ?>">&larr; Students</a><div class="card mt-3 mb-4"><div class="card-body p-4"><h1 class="h3"><?= e($student['first_name'] . ' ' . $student['last_name']) ?></h1><p class="text-secondary"><?= e($student['email']) ?></p><div class="row g-3"><div class="col-6 col-md-3"><span class="text-secondary d-block">XP</span><strong class="h4"><?= (int)$student['total_xp'] ?></strong></div><div class="col-6 col-md-3"><span class="text-secondary d-block">Level</span><strong class="h4"><?= (int)$student['level'] ?></strong></div><div class="col-6 col-md-3"><span class="text-secondary d-block">Streak</span><strong class="h4"><?= (int)$student['current_streak'] ?></strong></div><div class="col-6 col-md-3"><span class="text-secondary d-block">Status</span><strong class="h4"><?= e(ucfirst($student['status'])) ?></strong></div></div></div></div><div class="card mb-4"><div class="card-body"><h2 class="h5">Enrolled courses</h2><?php foreach ($courses as $course): $total = (int)$course['total_lessons']; $completed = (int)$course['completed_lessons']; ?><div class="border-bottom py-2"><strong><?= e($course['title']) ?></strong><span class="small text-secondary ms-2"><?= $completed ?>/<?= $total ?> lessons</span><?php if ($course['completed_at']): ?><span class="badge text-bg-success float-end">Completed</span><?php endif; ?></div><?php endforeach; ?><?php if (!$courses): ?><p class="text-secondary">No enrollments.</p><?php endif; ?></div></div><div class="row g-4"><div class="col-md-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Achievements</h2><?php foreach ($achievements as $item): ?><span class="badge text-bg-primary me-1 mb-2"><?= e($item['name']) ?></span><?php endforeach; ?><?php if (!$achievements): ?><p class="text-secondary">None.</p><?php endif; ?></div></div></div><div class="col-md-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Badges</h2><?php foreach ($badges as $item): ?><span class="badge text-bg-success me-1 mb-2"><?= e($item['name']) ?></span><?php endforeach; ?><?php if (!$badges): ?><p class="text-secondary">None.</p><?php endif; ?></div></div></div></div></div>
<?php require __DIR__ . '/../includes/footer.php'; ?>
